Definition HM_STACK : Z := 144 + AFS_STACK.

Definition hm_W (lo : Z) (sp : word) (P ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P + O_PR_HDR, P + O_PR_HDR + 40); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]%Z.

Definition hm_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P verb : Z) (h : hdrv) (LF : list fframe) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (hm_W lo sp P ff fp) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' (P + O_PR_HDR) (HdrCells (mkHV (hv_mp h) (hv_ml h) (hv_tp h) (hv_tl h) (hv_ver h) verb))
    /\ fresh_frame H LF 0 ff fp /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.      (* [comment removed for export] *)

Definition hm_stmt : Prop := forall (P verb lo shi : Z) (h : hdrv) (LF : list fframe)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m (P + O_PR_HDR) (HdrCells h) -> hv_ml h = 0 -> 1 <= verb < 2^32 ->
  stk asegs m lo (bv_unsigned sp) -> lo + HM_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> stack0 m lo shi ->
  0 <= P -> aapp P 256 -> P mod 8 = 0 -> accessible m P 256 -> fsobj H LF P 256 ->
  evt asegs (hm_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P verb h LF lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (P + 80)) (Z_to_bv 64 verb) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_HEADER_SET_METHOD) fc None m (seg_rom asegs)).
