Lemma hm_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word)
    (P verb spa lo shi ff fp : Z) (h : hdrv) (LF : list fframe) (m mx : mem) (j56 v16 hjunk sh8 : list byte) (bflag : byte),
  (pcv = Z_to_bv 64 AHM_RET_RS \/ pcv = ret_pc (Z_to_bv 64 AHM_RET_RS)) ->
  rw_cells asegs mx (bv_unsigned sp + -128) [CB 56 j56] ->
  rw_cells asegs mx (bv_unsigned sp + -72) [C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells asegs mx (bv_unsigned sp + -144) [CB 16 v16] ->
  rw_cells asegs mx ff [CB 56 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 8 sh8] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo (bv_unsigned sp + -144) -> mem_inv asegs mx ->
  as_RFS H ((0, ff, fp) :: LF) mx -> fresh_frame H LF 0 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (hm_W lo sp P ff fp) m mx -> wmono asegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 8); (fp, fp + 1)]%Z mx m' -> wmono asegs mx m' ->
     rw_cells asegs m' (P + O_PR_HDR) (HdrCells (mkHV (hv_mp h) (hv_ml h) (hv_tp h) (hv_tl h) (hv_ver h) verb))) ->
  lo + HM_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (hm_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P verb h LF lo shi m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 verb) (Z_to_bv 64 (P + 80)) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880)
             s8 s9 s10 s11 t3' t4' t5' t6')
        F pcv fc None mx (seg_rom asegs)).
